mapper.select:
SELECT id, request_id, key_id, model_alias, deployment_model,
       prompt_tokens, completion_tokens, total_tokens, cost,
       latency_ms, status, error_type, tenant_id, created_at,
       retry_count, fallback_used, served_alias, call_type, target_name,
       project_id, trace_id
FROM call_logs
WHERE 1 = 1

    AND tenant_id = #{tenantId,jdbcType=VARCHAR}


    AND project_id = #{projectId,jdbcType=VARCHAR}


    AND model_alias = #{model,jdbcType=VARCHAR}


    AND key_id = #{keyId,jdbcType=VARCHAR}


    AND status = #{status,jdbcType=INTEGER}


    AND created_at >= #{from,jdbcType=TIMESTAMP}


    AND created_at <= #{to,jdbcType=TIMESTAMP}

ORDER BY id DESC
LIMIT #{limit,jdbcType=INTEGER} OFFSET #{offset,jdbcType=INTEGER}

SELECT COUNT(*)
FROM call_logs
WHERE key_id = #{keyId,jdbcType=VARCHAR}
